/* Dark Mode Toggle */
function toggleDarkMode() {
  const isDark = document.body.classList.toggle('dark-mode');
  const moonIcon = document.getElementById('themeIconMoon');
  const sunIcon = document.getElementById('themeIconSun');
  if (moonIcon && sunIcon) {
    moonIcon.style.display = isDark ? 'none' : 'block';
    sunIcon.style.display = isDark ? 'block' : 'none';
  }
}

/* Cute Kawaii Sound Effect (Web Audio API) */
function playKawaiiSound(type) {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const now = ctx.currentTime;

    if (type === 'chime') {
      const notes = [587.33, 783.99, 1046.5];
      notes.forEach((freq, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, now + idx * 0.08);
        gain.gain.setValueAtTime(0.12, now + idx * 0.08);
        gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.08 + 0.22);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + idx * 0.08);
        osc.stop(now + idx * 0.08 + 0.23);
      });
    } else if (type === 'pop') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(420, now);
      osc.frequency.exponentialRampToValueAtTime(920, now + 0.11);
      gain.gain.setValueAtTime(0.14, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.13);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.14);
    } else {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(520, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.09);
      osc.frequency.exponentialRampToValueAtTime(620, now + 0.16);
      gain.gain.setValueAtTime(0.14, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.19);
    }
  } catch (e) {
    // Optional sound
  }
}

/* Female Spanish voices, best first. Helena is Catita's favorite. */
const FEMALE_VOICE_NAMES = [
  'helena', 'elena', 'dalia', 'elvira', 'salome', 'camila', 'paloma', 'ximena', 'larissa',
  'sabina', 'laura', 'paulina', 'monica', 'mónica', 'lucia', 'lucía',
  'google español'
];
const MALE_VOICE_NAMES = ['tomas', 'tomás', 'jorge', 'alvaro', 'álvaro', 'pablo', 'raul', 'raúl', 'gonzalo', 'diego', 'mateo', 'jose', 'josé'];
const VOICE_STORAGE_KEY = 'tomasito-voice';

function getSpanishVoices() {
  if (!('speechSynthesis' in window)) return [];
  return window.speechSynthesis
    .getVoices()
    .filter((v) => v.lang && v.lang.toLowerCase().startsWith('es'));
}

function scoreVoice(voice) {
  const name = voice.name.toLowerCase();
  if (MALE_VOICE_NAMES.some((m) => name.includes(m))) return -100;
  let score = 0;
  const idx = FEMALE_VOICE_NAMES.findIndex((f) => name.includes(f));
  if (idx >= 0) score += 50 - idx;
  if (name.includes('natural') || name.includes('online')) score += 40;
  if (voice.lang.toLowerCase() === 'es-ar') score += 10;
  return score;
}

function getBestKawaiiSpanishVoice() {
  const voices = getSpanishVoices();
  if (!voices.length) return null;

  const saved = localStorage.getItem(VOICE_STORAGE_KEY);
  const savedVoice = saved && voices.find((v) => v.name === saved);
  if (savedVoice) return savedVoice;

  return [...voices].sort((a, b) => scoreVoice(b) - scoreVoice(a))[0];
}

function populateVoiceSelect() {
  const select = document.getElementById('voiceSelect');
  if (!select) return;
  const voices = getSpanishVoices()
    .filter((v) => scoreVoice(v) > -100)
    .sort((a, b) => scoreVoice(b) - scoreVoice(a));
  if (!voices.length) return;

  const best = getBestKawaiiSpanishVoice();
  select.innerHTML = voices
    .map((v) => {
      const label = v.name.replace('Microsoft ', '').replace(' - Spanish', ' -');
      const selected = best && v.name === best.name ? 'selected' : '';
      return `<option value="${v.name}" ${selected}>${label}</option>`;
    })
    .join('');
}

function changeVoice(name) {
  localStorage.setItem(VOICE_STORAGE_KEY, name);
  stopTomasitoVoice();
}

function updateSpeakButtonUI(speaking) {
  isTomasitoSpeaking = speaking;
  const btn = document.getElementById('btnSpeakToggle');
  if (!btn) return;
  if (speaking) {
    btn.textContent = 'Detener voz';
    btn.classList.add('speaking');
  } else {
    btn.textContent = 'Escuchar voz Kawaii';
    btn.classList.remove('speaking');
  }
}

function stopTomasitoVoice() {
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
  }
  updateSpeakButtonUI(false);
}

function renderPlaceCards() {
  const grid = document.getElementById('placesGrid');
  if (!grid) return;

  grid.innerHTML = placesData
    .map((place) => {
      const isSelected = place.id === activePlaceId;
      return `
        <article
          class="place-card ${isSelected ? 'active' : ''}"
          onclick="selectPlace('${place.id}')"
          role="button"
          tabindex="0"
          aria-label="${place.name}"
        >
          <img src="${place.photoUrl}" alt="${place.name}" class="card-thumb-img" style="border-color:${place.accentColor};" />
          <div style="display:flex; align-items:center; justify-content:space-between;">
            <span class="card-number" style="background:${place.accentColor};">${place.number}</span>
            <span style="font-size:0.74rem; font-weight:700; color:${place.accentColor};">${place.badgeText}</span>
          </div>
          <h3 class="card-title">${place.name}</h3>
          <p class="card-desc">${place.shortDesc}</p>
          <div class="card-ages">${place.agesText}</div>
        </article>
      `;
    })
    .join('');
}

function updateShowcase(place) {
  const showcase = document.getElementById('placeShowcase');
  const badge = document.getElementById('activeBadge');
  const title = document.getElementById('activeTitle');
  const sceneContainer = document.getElementById('animatedSceneContainer');
  const speechText = document.getElementById('tomasitoSpeechText');
  const featuresList = document.getElementById('activeFeaturesList');
  const tabPhoto = document.getElementById('tabPhotoBtn');
  const tabDrawing = document.getElementById('tabDrawingBtn');

  if (showcase) showcase.style.borderColor = place.accentColor;
  if (badge) {
    badge.style.background = place.accentColor;
    badge.textContent = `Parada ${place.number}: ${place.badgeText}`;
  }
  if (title) title.textContent = place.name;

  if (tabPhoto && tabDrawing) {
    tabPhoto.classList.toggle('active', currentPlaceVisualMode === 'photo');
    tabDrawing.classList.toggle('active', currentPlaceVisualMode === 'drawing');
  }

  if (sceneContainer) {
    if (currentPlaceVisualMode === 'photo') {
      sceneContainer.innerHTML = `
        <img src="${place.photoUrl}" alt="${place.name}" class="place-photo-img" />
        <div class="photo-overlay-caption">
          <span>${place.photoCaption}</span>
          <span style="color:#F97316;">Salta, Argentina</span>
        </div>
      `;
    } else {
      sceneContainer.innerHTML = `
        <img src="${place.kawaiiUrl}" alt="${place.name} estilo kawaii" class="place-photo-img" />
        <div class="photo-overlay-caption">
          <span>${place.photoCaption} (Dibujo Kawaii)</span>
          <span style="color:#10B981;">Estilo Tomasito</span>
        </div>
      `;
    }
  }

  if (speechText) speechText.textContent = place.tomasitoSpeech;

  if (featuresList) {
    featuresList.innerHTML = place.highlights
      .map(
        (item) =>
          `<span class="feature-chip" style="border-color:${place.accentColor};">${item}</span>`
      )
      .join('');
  }
}

function setPlaceVisualMode(mode) {
  currentPlaceVisualMode = mode;
  const current = placesData.find((p) => p.id === activePlaceId);
  if (current) updateShowcase(current);
}

function selectPlace(placeId) {
  const found = placesData.find((p) => p.id === placeId);
  if (!found) return;
  stopTomasitoVoice();
  activePlaceId = placeId;
  renderPlaceCards();
  updateShowcase(found);
  triggerTomasitoTrick('jump');
}

function triggerTomasitoTrick(action) {
  const jumpWrapper = document.getElementById('puppyJumpWrapper');
  const tail = document.getElementById('puppyTail');
  const bone = document.getElementById('puppyBone');
  const earL = document.getElementById('earLeft');
  const earR = document.getElementById('earRight');
  const statusLabel = document.getElementById('tomasitoStatus');

  if (action === 'jump' && jumpWrapper) {
    playKawaiiSound('bark');
    jumpWrapper.classList.remove('puppy-jump');
    void jumpWrapper.offsetWidth;
    jumpWrapper.classList.add('puppy-jump');
    if (statusLabel) statusLabel.textContent = 'Tomasito da un gran salto de alegría';
    setTimeout(() => jumpWrapper.classList.remove('puppy-jump'), 950);
  } else if (action === 'wag' && tail) {
    playKawaiiSound('pop');
    const isFast = tail.classList.toggle('tail-fast');
    if (statusLabel) {
      statusLabel.textContent = isFast
        ? 'Tomasito mueve su colita súper rápido'
        : 'Tomasito mueve su colita suave';
    }
  } else if (action === 'bone' && bone) {
    playKawaiiSound('pop');
    const isHidden = bone.classList.toggle('bone-hidden');
    if (statusLabel) {
      statusLabel.textContent = isHidden
        ? 'El huesito desapareció y Tomasito sonríe'
        : 'El huesito blanco apareció de nuevo';
    }
  } else if (action === 'ears' && earL && earR) {
    playKawaiiSound('pop');
    earL.classList.remove('ear-left-party');
    earR.classList.remove('ear-right-party');
    void earL.offsetWidth;
    earL.classList.add('ear-left-party');
    earR.classList.add('ear-right-party');
    if (statusLabel) statusLabel.textContent = 'Tomasito mueve solamente sus orejitas';
    setTimeout(() => {
      earL.classList.remove('ear-left-party');
      earR.classList.remove('ear-right-party');
    }, 1700);
  }
}

function setTomasitoViewMode(mode) {
  const svgEl = document.getElementById('tomasitoSvg');
  const photoCartoon = document.getElementById('tomasitoCartoonImg');
  const photoReal = document.getElementById('tomasitoRealImg');

  if (!svgEl || !photoCartoon || !photoReal) return;

  svgEl.style.display = mode === 'animated' ? 'block' : 'none';
  photoCartoon.style.display = mode === 'cartoon' ? 'block' : 'none';
  photoReal.style.display = mode === 'real' ? 'block' : 'none';
}

function speakCurrentPlace() {
  if (!('speechSynthesis' in window)) return;

  // Toggle: if already speaking, stop immediately
  if (isTomasitoSpeaking || window.speechSynthesis.speaking) {
    stopTomasitoVoice();
    return;
  }

  const current = placesData.find((p) => p.id === activePlaceId);
  if (!current) return;

  playKawaiiSound('chime');
  window.speechSynthesis.cancel();

  const utterance = new SpeechSynthesisUtterance(current.tomasitoSpeech);
  const chosenVoice = getBestKawaiiSpanishVoice();
  if (chosenVoice) utterance.voice = chosenVoice;
  utterance.lang = chosenVoice ? chosenVoice.lang : 'es-AR';
  utterance.pitch = 1.25; // Sweet but natural (1.8 sounded robotic)
  utterance.rate = 0.95; // Calm, easy to follow for kids and grandparents

  utterance.onstart = () => updateSpeakButtonUI(true);
  utterance.onend = () => updateSpeakButtonUI(false);
  utterance.onerror = () => updateSpeakButtonUI(false);

  updateSpeakButtonUI(true);
  window.speechSynthesis.speak(utterance);
}

if ('speechSynthesis' in window) {
  window.speechSynthesis.onvoiceschanged = () => {
    populateVoiceSelect();
  };
}

document.addEventListener('DOMContentLoaded', () => {
  renderPlaceCards();
  updateShowcase(placesData[0]);
  populateVoiceSelect();
});
